use std::fmt::Write as _;
use std::io::Write as _;
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 8;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= dims.width || y >= dims.height) {
        return;
    }
    let w = i32(dims.width);
    let h = i32(dims.height);
    var n: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {
        for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                n = n + src[u32(ny * w + nx)];
            }
        }
    }
    let i = y * dims.width + x;
    let alive = src[i] == 1u;
    var next: u32 = 0u;
    if (n == 3u || (alive && n == 2u)) {
        next = 1u;
    }
    dst[i] = next;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let header = lines.next().ok_or("empty input file")?;
    let nums: Vec<&str> = header.split_whitespace().collect();
    if nums.len() != 3 {
        return Err(format!(
            "header must be `<width> <height> <generations>`, got {header:?}"
        ));
    }
    let num = |s: &str, what: &str, lo: u32, hi: u32| -> Result<u32, String> {
        let v: u32 = s
            .parse()
            .map_err(|_| format!("invalid {what}: {s:?}"))?;
        if v < lo || v > hi {
            return Err(format!("{what} {v} out of range {lo}..={hi}"));
        }
        Ok(v)
    };
    let width = num(nums[0], "width", 1, 512)?;
    let height = num(nums[1], "height", 1, 512)?;
    let generations = num(nums[2], "generations", 0, 1000)?;

    let mut cells = Vec::with_capacity((width * height) as usize);
    for row in 0..height {
        let line = lines
            .next()
            .ok_or_else(|| format!("expected {height} rows, found {row}"))?;
        let before = cells.len();
        for tok in line.split_whitespace() {
            for c in tok.chars() {
                match c {
                    '0' => cells.push(0),
                    '1' => cells.push(1),
                    _ => return Err(format!("row {}: invalid cell {c:?}", row + 1)),
                }
            }
        }
        let got = cells.len() - before;
        if got != width as usize {
            return Err(format!(
                "row {}: expected {width} cells, found {got}",
                row + 1
            ));
        }
    }
    if lines.next().is_some() {
        return Err(format!("more than {height} rows in input"));
    }
    Ok(Grid {
        width,
        height,
        generations,
        cells,
    })
}

fn run_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        force_fallback_adapter: false,
        compatible_surface: None,
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor {
        label: Some("life"),
        required_features: wgpu::Features::empty(),
        required_limits: wgpu::Limits::downlevel_defaults(),
        ..Default::default()
    }))
    .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let dims = [grid.width, grid.height];
    let dims_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("dims"),
        contents: &u32s_to_bytes(&dims),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let cell_usage =
        wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("cells a"),
        contents: &u32s_to_bytes(&grid.cells),
        usage: cell_usage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("cells b"),
        size,
        usage: cell_usage,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("life shader"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("life step"),
        layout: None,
        module: &module,
        entry_point: Some("step"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let bind = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: dims_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: dst.as_entire_binding(),
                },
            ],
        })
    };
    // Ping-pong: even generations read A and write B, odd ones the reverse.
    let a_to_b = bind(&buf_a, &buf_b);
    let b_to_a = bind(&buf_b, &buf_a);

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: None });
    for g in 0..grid.generations {
        // A separate pass per generation makes each one see the previous one's
        // complete output.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, if g % 2 == 0 { &a_to_b } else { &b_to_a }, &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = if grid.generations % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|_| "GPU readback was dropped".to_string())?
        .map_err(|e| format!("GPU readback failed: {e}"))?;
    let data = slice.get_mapped_range();
    let cells = data
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    drop(data);
    readback.unmap();
    Ok(cells)
}

fn u32s_to_bytes(v: &[u32]) -> Vec<u8> {
    v.iter().flat_map(|x| x.to_le_bytes()).collect()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu-life <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {path}: {e}");
            return ExitCode::from(1);
        }
    };
    let grid = match parse(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("invalid input: {e}");
            return ExitCode::from(1);
        }
    };
    let cells = match run_gpu(&grid) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::from(1);
        }
    };

    let w = grid.width as usize;
    let mut out = String::with_capacity(cells.len() * 2 + 32);
    for row in cells.chunks_exact(w) {
        for (i, c) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            out.push(if *c == 1 { '1' } else { '0' });
        }
        out.push('\n');
    }
    let alive = cells.iter().filter(|&&c| c == 1).count();
    let _ = writeln!(out, "ALIVE {alive}");
    let mut stdout = std::io::stdout().lock();
    if stdout.write_all(out.as_bytes()).and_then(|_| stdout.flush()).is_err() {
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}

