use std::fmt::Write as _;
use std::io::Write as _;
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 8;

const SHADER: &str = r#"
struct Dims {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn step(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= dims.width || y >= dims.height) {
        return;
    }
    let w = i32(dims.width);
    let h = i32(dims.height);
    var n: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {
        for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                n = n + src[u32(ny * w + nx)];
            }
        }
    }
    let i = y * dims.width + x;
    let alive = src[i] == 1u;
    var next: u32 = 0u;
    if (n == 3u || (alive && n == 2u)) {
        next = 1u;
    }
    dst[i] = next;
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse(text: &str) -> Result<Grid, String> {
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let header = lines.next().ok_or("empty input file")?;
    let nums: Vec<&str> = header.split_whitespace().collect();
    if nums.len() != 3 {
        return Err(format!(
            "header must be `<width> <height> <generations>`, got {header:?}"
        ));
    }
    let num = |s: &str, what: &str, lo: u32, hi: u32| -> Result<u32, String> {
        let v: u32 = s
            .parse()
            .map_err(|_| format!("invalid {what}: {s:?}"))?;
        if v < lo || v > hi {
            return Err(format!("{what} {v} out of range {lo}..={hi}"));
        }
        Ok(v)
    };
    let width = num(nums[0], "width", 1, 512)?;
    let height = num(nums[1], "height", 1, 512)?;
    let generations = num(nums[2], "generations", 0, 1000)?;

    let mut cells = Vec::with_capacity((width * height) as usize);
    for row in 0..height {
        let line = lines
            .next()
            .ok_or_else(|| format!("expected {height} rows, found {row}"))?;
        let before = cells.len();
        for tok in line.split_whitespace() {
            for c in tok.chars() {
                match c {
                    '0' => cells.push(0),
                    '1' => cells.push(1),
                    _ => return Err(format!("row {}: invalid cell {c:?}", row + 1)),
                }
            }
        }
        let got = cells.len() - before;
        if got != width as usize {
            return Err(format!(
                "row {}: expected {width} cells, found {got}",
                row + 1
            ));
        }
    }
    if lines.next().is_some() {
        return Err(format!("more than {height} rows in input"));
    }
    Ok(Grid {
        width,
        height,
        generations,
        cells,
    })
}

